+
+	if (entry->leg)
+		list_del(&entry->leg_list_node);
+
+	sparx5_rr_neigh_entry_offload_mark(entry, false);
+	sparx5_rr_neigh_entry_remove(sparx5, entry);
+	netdev_put(entry->key.dev, &entry->dev_tracker);
+
+	kfree(entry);
+}
